<template>
  <view :class="['app-frame','page-'+view,{'no-home-bar':!showHomeBar,'is-practicing':['practice','conjugation'].includes(view)&&activeMode==='vocabulary','is-oral':activeMode==='oral','is-grammar':activeMode==='grammar'}]">
    <view class="main-area" :inert="settingsOpen||quickImportOpen||learningAdjustOpen||modeDrawerOpen||undefined" :aria-hidden="settingsOpen||quickImportOpen||learningAdjustOpen||modeDrawerOpen||undefined">
      <header v-if="showHomeBar" class="topbar"><view class="mode-switch-space" aria-hidden="true"/><view class="mobile-brand"><image class="brand-mark small app-icon" :src="appIcon" mode="aspectFit" :alt="appManifest.name" /><text>{{ appManifest.name }}</text></view><view class="desktop-caption"><text>{{ appManifest.name }}</text><text>Cap sur le français</text></view><view class="topbar-actions"><text v-if="!studyView" class="date-label">{{ dateLabel }}</text></view></header>
      <Transition :name="view==='lessons'?'lesson-entrance':'page-fade'" mode="out-in">
      <main v-if="activeMode==='oral'" key="oral" class="content oral-content"><OralMode @restore-file="restore" @home="oralHome=$event" @notice="notice" @modes="modeDrawerOpen=true" @settings="openSettings" /></main>
      <main v-else-if="activeMode==='grammar'" key="grammar" class="content grammar-content"><GrammarMode @home="grammarHome=$event" ref="grammarMode" :settings="grammarSettings" :active="!settingsOpen&&!modeDrawerOpen" @notice="notice" @settings="openSettings" /></main>
      <main v-else :key="view+(view==='lesson'?':'+previewLessonKey:['recite','practice'].includes(view)?':'+selectedKey:'')" class="content" :class="{ 'practice-content': ['practice','conjugation'].includes(view) }">
        <view v-if="fatal" class="glass empty-state"><Icon name="info" /><Bi zh="本地记录暂时无法读取" fr="Les données locales sont inaccessibles." /><text>{{ fatal }}</text><button hover-class="none" class="button primary" @click="load"><Bi zh="重试" fr="Réessayer" /></button></view>
        <template v-else-if="!ready"><view class="glass empty-state"><view class="spinner" /><Bi zh="正在打开学习空间" fr="Ouverture de votre espace…" /></view></template>
        <template v-else-if="view==='books'"><HomeDashboard :learn-size="preferredGroupSize(data.settings)" :review-size="preferredGroupSize(data.settings,'review')" @learning-adjust="openLearningAdjust" :book-title="selectedBookTitle" :lesson-id="currentPackage?.lesson.id" :total="currentStats?.total||0" :completed="currentStats?.completed||0" :today="todayCount" :due="dueReviewCount" :review-in-progress="hasReviewInProgress" :review-badge="!!practiceBadges.review?.pending" :busy="busy" :last-label="lastPractice?.label" @book="view='manuals'" @lesson="chooseLesson" @recite="openRecitation()" @practice="startLearningPractice" @review="startTodayReview" @resume="resumeLastPractice" /></template>
        <template v-else-if="view==='manuals'"><view class="picker-heading"><button hover-class="none" class="icon-button back-control" @click="navigate('books')" aria-label="返回 / Retour"><Icon name="back" /></button><view class="page-heading"><h1>教材<span>Manuels</span></h1></view></view><BookPicker show-imported :selected="selectedBookId" :lessons="inspireLessons.length" :book-counts="bookLessonCounts" :imported="importedCourses.filter(p=>p.book.id==='imported').length" @select="selectBook" /></template>
        <template v-else-if="view==='lessons'"><view class="picker-heading"><button hover-class="none" class="icon-button back-control" @click="navigate('books')" aria-label="返回 / Retour"><Icon name="back" /></button><view class="page-heading"><h1>Lesson<span>{{ selectedBookTitle||'Inspire 1' }}</span></h1></view></view><view v-if="['imported'].includes(selectedBookId)" class="imported-course-actions"><button class="text-button" hover-class="none" @click="newImportLesson"><Icon name="plus"/><Bi zh="新增 Lesson" fr="Nouvelle leçon" small/></button><button class="button secondary" hover-class="none" @click="openWordImport()"><Icon name="plus"/><Bi zh="导入单词" fr="Importer" small/></button></view><view v-if="['imported'].includes(selectedBookId)&&!lessonEntries.length" class="empty-state glass"><Icon name="cards"/><Bi zh="导入单词，开始学习" fr="Importez vos premiers mots"/></view><LessonPicker :entries="lessonEntries" :selected="selectedKey" @select="selectLesson" @preview="openLesson" @pin="toggleLessonPin" @add="openWordImport" /></template>
        <template v-else-if="view==='lesson' && currentPackage">
          <button hover-class="none" class="back-link" @click="navigate('lessons')"><Icon name="back" /><Bi zh="返回课次" fr="Toutes les leçons" inline /></button><view class="page-heading"><view><text class="eyebrow">{{ currentPackage.book.title }} · {{ currentPackage.lesson.id }}</text><h1>{{ currentPackage.lesson.title.split(' · ')[0] }}<span>{{ currentPackage.lesson.title.split(' · ')[1] || '单词 · Vocabulaire' }}</span></h1></view><button hover-class="none" class="help-inline" @click="help='learning'" aria-label="学习帮助 / Aide"><text>?</text></button></view>
          <view class="lesson-summary glass"><view v-for="stat in [{key:'practice',zh:'待学',fr:'à apprendre'},{key:'review',zh:'复习本',fr:'à réviser'},{key:'known',zh:'已会',fr:'acquis'}]" :key="stat.key"><strong>{{ currentStats[stat.key] }}</strong><Bi :zh="stat.zh" :fr="stat.fr" small /></view></view>
          <view v-if="visibleWords.length" class="lesson-word-list glass"><view v-for="word in visibleWords" :key="word.id"  :class="['lesson-word-row',{'is-learned':getProgress(data,currentPackage,word).notebook!=='practice'}]"><button hover-class="none" class="lesson-word-main" :data-notebook-key="wordKey(currentPackage,word)" @click="openWordPreview(currentPackage,word)"><text lang="fr">{{ word.forms.map(f=>displayForm(word,f)).join(' / ') }}</text><view class="lesson-word-info"><text class="pos">{{ word.sourcePos||word.pos }}</text><Bi v-if="currentPackage.importedLesson&&getProgress(data,currentPackage,word).notebook!=='practice'" :zh="wordNotebookLabel(currentPackage,word).zh" :fr="wordNotebookLabel(currentPackage,word).fr" small/><text v-if="currentPackage.importedLesson&&!word.conjugation" class="imported-date">{{ data.importedWords?.[wordKey(currentPackage,word)]?.date }}</text></view><Icon name="arrow" /></button><button hover-class="none" :class="['icon-button','favorite',{marked:data.favorites[wordKey(currentPackage,word)]}]" v-if="!word.conjugation" @click="favorite(word)" :aria-label="data.favorites[wordKey(currentPackage,word)]?'取消收藏 / Retirer des favoris':'收藏 / Ajouter aux favoris'"><SuccessIcon name="heart" :active="!!data.favorites[wordKey(currentPackage,word)]" :item-key="'word:'+(word.lexiconId||word.id)" /></button><button v-if="currentPackage.importedLesson&&!word.conjugation" hover-class="none" class="icon-button remove-imported" @click="requestRemoveImported(wordContext(data,currentPackage,word))" aria-label="移出导入本 / Retirer"><Icon name="trash"/></button></view></view>
          <view v-if="!visibleWords.length" class="empty-state glass"><Bi zh="没有找到这个词" fr="Aucun mot trouvé." /></view>
          <view class="lesson-management"><button hover-class="none" class="text-button" :class="{marked:data.pinnedLessons?.[packageKey(currentPackage)]}" @click="toggleLessonPin(currentPackage)"><SuccessIcon name="star" :active="!!data.pinnedLessons?.[packageKey(currentPackage)]" :item-key="'lesson:'+packageKey(currentPackage)" /><Bi zh="重点 Lesson" fr="Prioritaire" small /></button></view>
          <view class="lesson-dock glass learning-choice-dock"><button hover-class="none" class="button primary" :disabled="busy" @click="openRecitation()"><Icon name="cards" /><Bi zh="开始背诵" fr="Mémoriser" /></button><button hover-class="none" class="button secondary" :disabled="busy" @click="startLearningPractice"><Icon name="edit" /><Bi zh="直接练习" fr="Pratiquer" /></button></view>
        </template>
        <template v-else-if="view==='recite'&&currentPackage"><view class="recitation-top"><button hover-class="none" class="icon-button back-control" @click="navigate(importedReciting?importedOrigin:recitationOrigin)" aria-label="返回 / Retour"><Icon name="back" /></button><view><text>{{ currentPackage.lesson.id }}</text><Bi zh="背诵" fr="Mémoriser" small /></view><text class="muted">{{ currentStats.completed }} / {{ currentStats.total }}</text></view><RecitationPanel :key="importedReciting?data.importedRecitationIds.join(','):selectedKey" :pkg="currentPackage" :data="data" :playing="playing" :busy="busy" @audio="play" @audio-stop="stopPlaying" @detail="openWordPreview(currentPackage,$event)" @practice="startLearningPractice" @conjugation="openConjugationPractice(currentPackage)" /></template>
        <template v-else-if="view==='conjugation'&&activeConjugation"><ConjugationPractice :state="activeConjugation" :today-review-done="dueReviewCount===0" :busy="busy" @close="closeConjugationPractice" @answer="submitConjugation" @continue="continueConjugation" @hint="showConjugationHint" @audio="play"/></template>
        <template v-else-if="view==='practice' && currentPackage && currentSession">
          <view class="practice-top"><button hover-class="none" class="icon-button back-control" @click="backFromPractice" aria-label="返回 / Retour"><Icon name="back" /></button><view class="practice-location"><text>{{ currentSession.mode==='review'?'复习 · Révision':currentSession.mode==='errors'?'错题 · Erreurs':currentSession.mode==='favorites'?'收藏 · Favoris':currentSession.importedPractice?currentImportedCourse?.lesson.id:currentPackage.lesson.id }}</text><text v-if="currentSession.mode!=='review'" class="muted">{{ currentSession.mode==='review'?'':currentSession.mode==='errors'?'错题专练 · Correction':currentSession.mode==='favorites'?'收藏专练 · Entraînement':currentSession.mode==='direct'&&!currentSession.importedPractice?'单词专练 · Pratique':'学习 · Apprentissage' }}</text></view><text class="practice-count">{{ overallProgress.completed }} / {{ overallProgress.total }}</text><button hover-class="none" class="icon-button" @click="help='learning'" aria-label="练习帮助 / Aide"><Icon name="info" /></button></view>
          <view class="session-progress"><view :style="{width:overallProgress.percent+'%'}" /></view>
          <Transition name="round-step" mode="out-in"><view v-if="currentSession.phase==='done'" :key="'complete:'+currentSession.id" class="completion glass">
            <view class="completion-icon"><Icon name="check" /></view><h1>{{ todayReviewFinished?'真棒，已完成今日复习':lessonFinished?'本课完成':currentSession.deferredWordIds?.length?'本轮结束':'本轮完成' }}<span>{{ todayReviewFinished?'Bravo, les révisions du jour sont terminées !':lessonFinished?'Leçon terminée':'Session terminée' }}</span></h1>
            <view class="completion-stats"><view><strong>{{ currentSession.doneWords.length }}</strong><Bi zh="已完成" fr="mots terminés" small /></view><view><strong>{{ currentSession.stats.attempts?Math.round(currentSession.stats.correct/currentSession.stats.attempts*100)+'%':'—' }}</strong><Bi zh="正确率" fr="réussite" small /></view></view>
            <view v-if="newKnownEntries.length" class="new-known-summary"><Bi :zh="`新加入已会本 · ${newKnownEntries.length}`" fr="Nouveaux acquis" small /><button v-for="entry in newKnownEntries" :key="wordKey(entry.p,entry.w)" hover-class="none" @click="openWordPreview(entry.p,entry.w)"><text lang="fr">{{ entry.w.forms.map(f=>displayForm(entry.w,f)).join(' / ') }}</text><text>{{ entry.w.meanings.join('；') }}</text><Icon name="arrow" /></button></view>
            <view class="completion-actions"><button hover-class="none" class="button secondary back-action" @click="backFromPractice"><Icon name="back" /><Bi zh="返回" fr="Retour" small /></button><button hover-class="none" v-if="currentSession.pending.length" class="button primary" :disabled="busy" @click="continuePractice"><Icon name="arrow" /><Bi zh="继续练习" fr="Continuer" small /></button><button hover-class="none" v-else-if="currentSession.dictionaryPractice" class="button primary" @click="backFromPractice"><Bi zh="返回" fr="Retour" small/><Icon name="arrow"/></button><button hover-class="none" v-else-if="currentSession.importedPractice" class="button primary" @click="currentStats?.practice?startImportedExercises():startNextLesson()"><Bi :zh="currentStats?.practice?'继续练习':nextLesson?'下一课时':'选择 Lesson'" :fr="currentStats?.practice?'Continuer':nextLesson?'Leçon suivante':'Choisir une leçon'" small/><Icon name="arrow"/></button><button hover-class="none" v-else-if="currentSession.mode==='review'" class="button primary" @click="pendingConjugations(data,null,'review').length?openConjugationPractice(null,'review'):navigate('books')"><Bi :zh="pendingConjugations(data,null,'review').length?'变位复习':'首页'" :fr="pendingConjugations(data,null,'review').length?'Conjugaison':'Accueil'" small /><Icon name="check" /></button><button hover-class="none" v-else-if="currentSession.mode==='errors'&&pendingConjugations(data,null,'errors').length" class="button primary" @click="openConjugationPractice(null,'errors')"><Icon name="grammar"/><Bi zh="变位错题" fr="Conjugaison" small/></button><button hover-class="none" v-else-if="currentSession.mode==='favorites'&&pendingConjugations(data,null,'favorites').length" class="button primary" @click="openConjugationPractice(null,'favorites')"><Icon name="grammar"/><Bi zh="变位收藏" fr="Conjugaisons favorites" small/></button><button hover-class="none" v-else-if="pendingLessonConjugations" class="button primary" :disabled="busy" @click="openConjugationPractice(currentPackage)"><Icon name="grammar"/><Bi zh="变位练习" fr="Conjuguer" small/></button><button hover-class="none" v-else-if="lessonFinished" class="button primary" :disabled="busy" @click="startNextLesson"><Bi :zh="nextLesson?'下一课时':'选择 Lesson'" :fr="nextLesson?'Leçon suivante':'Choisir une leçon'" small /><Icon name="arrow" /></button><button hover-class="none" v-else class="button primary" @click="backFromPractice"><Icon name="back" /><Bi zh="返回" fr="Retour" small /></button></view>
          </view>
          <PracticePanel v-else-if="activeWord" ref="practicePanel" :key="currentSession.id" :pkg="currentPackage" :source-pkg="activeSourcePackage" :source-label="wordSourceLabel(currentPackage,activeWord)" :session="currentSession" :word="activeWord" :form="activeForm" :known="getProgress(data,currentPackage,activeWord).notebook==='known'" :allow-remove="false" @remove="removePracticeImported" @primary-meaning="choosePrimaryMeaning($event,{p:currentPackage,w:activeWord})" :favorite="!!data.favorites[wordKey(currentPackage,activeWord)]" :playing="playing" :busy="busy" :motion="data.settings.wordMotion" :article-mode="data.settings.articleMode||'choice'" @answer="answer" @next="next" @hint="hint" @retry-hint="retryHint" @known="markKnown" @favorite="favorite" @audio="play" @audio-stop="stopPlaying" /></Transition>
        </template>
        <template v-else-if="view==='notebook'">
          <view class="page-heading"><view><text class="eyebrow">LES MOTS QUI RESTENT</text><h1>你的词本<span>Chaque mot a sa place.</span></h1></view><button hover-class="none" class="help-inline" @click="help='notebook'" aria-label="词本帮助 / Aide"><text>?</text></button></view>
          <view class="tabs notebook-tabs"><button hover-class="none" v-for="tab in notebookTabs" :key="tab.id" :class="{active:notebookTab===tab.id}" @click="notebookTab=tab.id"><Bi :zh="tab.zh" :fr="tab.fr" small /><view v-if="tab.id==='errors'&&practiceBadges.errors?.pending" class="practice-badge" aria-label="有待练词 / À pratiquer" /></button></view>
          <view v-if="notebookTab==='review'" class="glass daily-review-dock"><Bi :zh="dueReviewCount+' 个到期词'" :fr="dueReviewCount+' mots à revoir'" /><button hover-class="none" class="button primary notebook-practice-action" :disabled="busy||(!dueReviewCount&&!hasReviewInProgress)" @click="startTodayReview"><Icon name="repeat" /><Bi :zh="hasReviewInProgress?'继续复习':'开始复习'" :fr="hasReviewInProgress?'Reprendre':'Réviser'" small /></button></view>
          <view v-if="notebookTab==='errors'" class="glass errors-practice-dock"><button hover-class="none" class="toggle-row" @click="setSetting('errorAutoRemove',data.settings.errorAutoRemove===false)"><Bi zh="复习两次后移出" fr="Retirer après 2 révisions" small /><SpringToggle :on="data.settings.errorAutoRemove!==false" /></button><button hover-class="none" class="button primary notebook-practice-action" :disabled="busy||(!errorWordCount&&!hasErrorsInProgress)" @click="startErrors"><Icon name="repeat" /><Bi :zh="hasErrorsInProgress?'继续错题':'练习错题'" :fr="hasErrorsInProgress?'Reprendre':'Corriger'" small /><view v-if="practiceBadges.errors?.pending" class="practice-badge" aria-label="有待练错题 / Erreurs à réviser" /></button></view>
          <view v-if="['imported'].includes(notebookTab)" class="glass daily-review-dock"><button class="button secondary" @click="openWordImport()"><Icon name="plus"/><Bi zh="导入单词" fr="Importer" small/></button><button class="button primary" @click="startImportedPractice"><Icon name="cards"/><Bi zh="开始学习" fr="Apprendre" small/></button></view>
          <view v-if="notebookTab==='favorites'" class="glass daily-review-dock"><Bi :zh="favoriteWordCount+' 个收藏词'" :fr="favoriteWordCount+' mots favoris'" /><button hover-class="none" class="button primary notebook-practice-action" :disabled="busy||(!favoriteWordCount&&!hasFavoritesInProgress)" @click="startFavorites"><Icon name="repeat" /><Bi :zh="hasFavoritesInProgress?'继续练习':'练习收藏'" :fr="hasFavoritesInProgress?'Reprendre':'Pratiquer'" small /></button></view>
          <view class="search-box notebook-search"><Icon name="search" /><input :adjust-position="false" v-model="search" placeholder="搜索词本 / Rechercher un mot" /></view>
          <view :key="notebookTab" class="notebook-panel"><view v-if="!notebookEntries.length" class="empty-state glass"><view class="empty-icon"><Icon name="notebook" /></view><Bi zh="这里还没有单词" fr="Aucun mot pour le moment" /><button hover-class="none" class="button secondary" @click="chooseLesson"><Bi zh="选择 Lesson" fr="Choisir une leçon" /></button></view>
            <view ref="notebookScroller" v-else class="glass review-word-list" @scroll.passive="moreNotebook" :class="{'compact-review':notebookTab==='review','all-notebook':notebookTab==='all'}"><view v-if="notebookTab==='all'&&notebookStart" :style="{height:notebookStart*64+'px',flexShrink:0}"/><template v-for="(entry,index) in notebookVisibleEntries" :key="wordKey(entry.p,entry.w)"><view v-if="notebookTab==='errors'?entry.errorDoneToday&&(index===0||!notebookEntries[index-1].errorDoneToday):notebookTab==='favorites'&&entry.practiceCount>0&&(index===0||notebookEntries[index-1].practiceCount===0)" class="practiced-divider"><Bi :zh="notebookTab==='errors'?'今日已复习':'已专练'" :fr="notebookTab==='errors'?'Révisés aujourd’hui':'Déjà pratiqués'" inline small /></view><view class="review-word-row" :class="{'reviewed-today':notebookTab==='errors'&&entry.errorDoneToday}"><button hover-class="none" class="notebook-entry-main" :data-notebook-key="wordKey(entry.p,entry.w)" role="button" tabindex="0" @keydown.enter.prevent="reviewDetail=entry" @keydown.space.prevent="reviewDetail=entry" @click="reviewDetail=entry"><view class="notebook-word-label"><text lang="fr">{{ entry.w.forms.map(f=>displayForm(entry.w,f)).join(' / ') }}</text><text class="entry-lesson">{{ wordSourceLabel(entry.p,entry.w) }}</text></view><view class="review-entry-meta"><text class="pos">{{ entry.w.sourcePos||entry.w.pos }}</text><Bi v-if="notebookTab==='imported'&&getProgress(data,entry.p,entry.w).notebook!=='practice'" :zh="wordNotebookLabel(entry.p,entry.w).zh" :fr="wordNotebookLabel(entry.p,entry.w).fr" small/><template v-if="notebookTab==='review'"><Bi v-if="(entry.cards||[entry.w]).some(w=>getProgress(data,entry.p,w).pendingLearning)" zh="待巩固" fr="À consolider" small/><Bi v-else :zh="'已学习 '+(entry.tenseEntry?entry.studyDays:studyDays(data,entry.p,entry.w,currentDate))+' 天'" :fr="'Jour '+(entry.tenseEntry?entry.studyDays:studyDays(data,entry.p,entry.w,currentDate))" small /><Bi :zh="reviewCountdown(entry)" :fr="reviewCountdown(entry,true)" small /></template><template v-if="notebookTab==='errors'"><Bi :zh="'错误 '+entry.errorCount+' 次'" :fr="entry.errorCount+' erreurs'" small /><Bi :zh="'复习 '+entry.practiceCount+' 次'" :fr="entry.practiceCount+' révisions'" small /></template><Bi v-else-if="notebookTab==='favorites'" :zh="'专练 '+entry.practiceCount+' 次'" :fr="entry.practiceCount+' entraînement'+(entry.practiceCount===1?'':'s')" small /></view><Icon name="arrow" /></button><button hover-class="none" :class="['icon-button','favorite',{marked:data.favorites[wordKey(entry.p,entry.w)]}]" v-if="!entry.w.conjugation" @click="favorite(entry.w,entry.p)" :aria-label="data.favorites[wordKey(entry.p,entry.w)]?'取消收藏 / Retirer des favoris':'收藏 / Favoris'"><SuccessIcon name="heart" :active="!!data.favorites[wordKey(entry.p,entry.w)]" :item-key="'word:'+(entry.w.lexiconId||entry.w.id)" /></button><button v-if="['imported'].includes(notebookTab)&&!entry.w.conjugation&&data.importedWords?.[wordKey(entry.p,entry.w)]" hover-class="none" class="icon-button remove-imported" @click="requestRemoveImported(entry)" aria-label="移出导入本 / Retirer des mots importés"><Icon name="trash"/></button></view></template><view v-if="notebookTailSpace" :style="{height:notebookTailSpace+'px',flexShrink:0}"/><view v-if="notebookEntries.length>=notebookLimit" class="notebook-load-sentinel" style="height:1px;flex-shrink:0" aria-hidden="true"/></view>
          </view>
        </template>
        <template v-else-if="view==='activity'">
          <view class="page-heading activity-heading"><view><text class="eyebrow">LES PETITS PROGRÈS</text><h1>每一天，都算数。<span>Votre chemin, jour après jour.</span></h1></view></view><view class="activity-stats"><view class="glass stat-card"><strong>{{ todayCount }}</strong><Bi zh="今日完成词数" fr="mots aujourd’hui" /></view><view class="glass stat-card"><strong>{{ shareStats.total }}</strong><Bi zh="累计背词" fr="mots appris" /></view><view class="glass stat-card"><strong>{{ Object.keys(data.activity).filter(k=>data.activity[k].words.length).length }}</strong><Bi zh="学习天数" fr="jours d’apprentissage" /></view></view><StudyCalendar :activity="dailyActivity" :library="data.library" @word="openWordPreview($event.p,$event.w)" />
        </template>
      </main>
      </Transition>
    </view>
    <Transition name="navigation-fade"><nav v-if="!settingsOpen&&activeMode==='vocabulary'&&!['practice','recite','conjugation'].includes(view)" class="mobile-nav glass" :inert="learningAdjustOpen||modeDrawerOpen||undefined" :aria-hidden="learningAdjustOpen||modeDrawerOpen||undefined"><button hover-class="none" v-for="n in navigation" :key="n.id" :class="{active:navActive===n.id}" @click="navigate(n.id)"><Icon :name="n.icon" /><Bi :zh="n.zh" :fr="n.fr" small /><view v-if="n.id==='books'?practiceBadges.review?.pending:n.id==='notebook'&&practiceBadges.errors?.pending" class="practice-badge" aria-label="有待练词 / À pratiquer" /></button></nav></Transition>
    <Transition name="page-fade"><QuickWordImport v-if="quickImportOpen" :destination="quickImportDestination" :lessons="importedCourses.filter(p=>p.book.id===quickImportDestination.bookId)" @destination="quickImportDestination={...quickImportDestination,lessonId:$event}" @new-lesson="newImportLesson" :library="data.library" :data="data" @close="quickImportOpen=false" @import="applyQuickImport"/></Transition>
    <Transition name="page-fade"><AppSettings v-if="settingsOpen" :initial-scope="settingsScope" :data="data" :data-ready="ready" :busy="busy" :notification-permission="notificationPermission" :grammar-settings="grammarSettings" @close="settingsOpen=false" @setting="setSetting" @grammar-setting="setGrammarSetting" @goal="setGoal" @notifications="toggleNotifications" @reminder-time="setReminderTime" @import="openImport" @backup="backup" @restore="restore" @share="shareOpen=true" @notice="notice" @mode="chooseMode" :inert="learningAdjustOpen||undefined" :aria-hidden="learningAdjustOpen||undefined" /></Transition>
    <Transition name="page-fade"><LearningAdjustPage v-if="learningAdjustOpen" :learn-size="preferredGroupSize(data.settings)" :review-size="preferredGroupSize(data.settings,'review')" :busy="busy" @close="closeLearningAdjust" @change="setSetting" /></Transition>
