async function runWordPractice(entry){if(entry.p.dictionary){let resolved;if(!await commit(d=>resolved=resolveDictionaryEntry(d,entry)))return;entry=resolved;}if(entry.p.book.id==='personal'&&!entry.fromImported){const pool=reviewPackage(data.value),ids=[wordKey(entry.p,entry.w)],key=sessionKey(pool,'direct',ids);if(await commit(d=>{startSession(d,pool,'direct',ids).dictionaryPractice=true;})){reviewDetail.value=null;selectedSessionKey.value=key;practiceReturnView.value=learningEntryView();view.value='practice';}return;}if(entry.conjugationOnly){await openConjugationPractice({...entry.p,words:[entry.w]},'errors');return;}if(entry.w.conjugation){await openConjugationPractice({...entry.p,words:entry.p.words.filter(w=>w.conjugation?.lemma===entry.w.conjugation.lemma)},entry.errorMode?'errors':'direct');return;}if(entry.errorMode&&errorPracticeState(data.value,entry.p,entry.w,currentDate.value).doneToday){notice('今天已复习 / Déjà révisé aujourd’hui.');return;}reviewDetail.value=null;if(entry.fromImported&&!entry.errorMode){selectedBookId.value=entry.importedLessonKey?.split(':')[0]||'imported';selectedKey.value=entry.importedLessonKey;await begin('direct',[wordKey(entry.p,entry.w)],reviewPackage(data.value),true,entry.importedLessonKey);}else await begin(entry.errorMode?'errors':'direct',[entry.w.id],entry.p);}

