function adjustmentContext(d,entry,create=false){
 if(entry.w.conjugation||isVerb(entry.w))return tenseEntry(d,entry.w,entry.p,create)||entry;
 const resolved=create?resolveDictionaryEntry(d,entry):entry,source=wordContext(d,resolved.p,resolved.w),p=d.library.find(item=>packageKey(item)===packageKey(source.p))||source.p,w=p.words?.find(item=>item.id===source.w.id)||source.w;return {...source,p,w};
}
function selectionStatus(entry,selection){return notebookSelectionStatus(data.value,adjustmentContext(data.value,entry),selection);}
async function adjustSelectedEntries(entry,selection,target){
 let resolved,result;if(!await commit(d=>{resolved=adjustmentContext(d,entry,true);result=applyNotebookSelection(d,resolved,selection,target);}))return null;
 if(result.skipped?.length)notice('已跳过复习词条：'+result.skipped.join('、')+' / Éléments en révision ignorés.');
 else if(target==='add-imported')notice('已加入导入本 / Ajouté aux mots importés.');
 else if(target==='remove-imported')notice('已移出导入本 / Retiré des mots importés.');
 if(data.value.conjugationSessions?.[conjugationKey.value]?.retired&&view.value==='conjugation')closeConjugationPractice();
 return entry.p.dictionary?{...entry,...resolved}:entry;
}
function requestMove(target){
