 if(target==='imported')target=moveSelectionState.value.imported?'remove-imported':'add-imported';
 const run=async()=>{const updated=await adjustSelectedEntries(entry,selection,target);if(updated){if(target==='favorite')moveDialog.value=updated;else{moveDialog.value=null;reviewDetail.value=updated;}}else if(!moveDialog.value){moveSelection.value=selection;moveDialog.value=entry;}};
 if(['known','favorite','add-imported','remove-imported'].includes(target)){run();return;}
 moveDialog.value=null;const name=moveTargets.find(t=>t.id===target),items=[...(selection.infinitive?['原形']:[]),...selection.tenses].join('、');
 confirmation.value={zh:'将'+items+'移到'+name.zh+'？',fr:'Déplacer la sélection vers « '+name.fr+' » ?',detail:'',cancel:()=>{moveSelection.value=selection;moveDialog.value=entry;},run};
}
