let preferenceTimer,preferencePending=false,preferenceQueue=Promise.resolve(),preferenceRevision=0,savedPreferences;
function flushPreferences(){clearTimeout(preferenceTimer);if(!preferencePending)return preferenceQueue;preferencePending=false;const revision=preferenceRevision,settings=clone(toRaw(data.value.settings));preferenceQueue=preferenceQueue.then(async()=>{await paintFeedback();try{await repo.savePreferences(settings);savedPreferences=settings;if(settings.reviewErrorRetry===false)for(const r of Object.values(data.value.progress))for(const f of Object.values(r.forms||{}))delete f.retryDue;for(const session of Object.values(data.value.sessions))if(session.mode==='errors')session.removeErrors=settings.errorAutoRemove!==false;}catch(e){if(revision===preferenceRevision&&savedPreferences){data.value.settings={...savedPreferences};applyColorTheme(colorThemeId(savedPreferences.colorTheme));}notice(e.message);}});return preferenceQueue;}
