async function startImportedPractice(p=null,resume=false){
 importedOrigin.value=learningEntryView();
 const book=view.value==='notebook'&&['imported'].includes(notebookTab.value)?notebookTab.value:selectedBookId.value;
 const course=p?.importedLesson?p:(currentImportedCourse.value?.book.id===book?currentImportedCourse.value:null)||importedCourses.value.find(p=>p.book.id===book&&packageKey(p)===selectedKey.value)||importedCourses.value.find(p=>p.book.id===book&&lessonStats(data.value,p).practice)||importedCourses.value.find(p=>p.book.id===book);
 if(!course){selectedBookId.value=book||'imported';navigate('lessons');return;}
 const key=packageKey(course),active=activeImportedSession(data.value,key);
 selectedBookId.value=course.book.id;selectedKey.value=key;
 if(resume&&active){if(!await commit(d=>{d.sessions[active.key].importedCourseLearning=true;rememberHomeSelection(d,course.book.id,key);}))return;practiceReturnView.value=importedOrigin.value;selectedSessionKey.value=active.key;importedReciting.value=false;view.value='practice';return;}
 const entries=course.words.filter(w=>!w.conjugation);
 if(!entries.length){if(pendingConjugations(data.value,course).length){await openConjugationPractice(course);return;}notice('本课已学完 / Leçon terminée.');navigate('lessons');return;}
 if(await commit(d=>{d.importedRecitationIds=entries.map(w=>w.id);d.importedRecitationLesson=key;rememberHomeSelection(d,course.book.id,key);})){importedReciting.value=true;stopPlaying();view.value='recite';}
}
async function startImportedExercises(){
 const key=view.value==='practice'?currentSession.value?.importedLessonKey:data.value.importedRecitationLesson;const course=importedCourses.value.find(p=>packageKey(p)===key);if(!course)return;
 const lessonKey=packageKey(course);
 if(activeImportedSession(data.value,lessonKey)){await startImportedPractice(course,true);return;}
 const waiting=waitingImportedSession(data.value,lessonKey);
 if(waiting){
  if(await commit(d=>{const run=d.sessions[waiting.key];run.importedCourseLearning=true;const pool=reviewPackage(d);appendLearningWords(d,pool,run,course.words.filter(isVocabularyWord).map(w=>w.id));continueRound(d,pool,waiting.key);rememberHomeSelection(d,course.book.id,lessonKey);})){practiceReturnView.value=importedOrigin.value;selectedSessionKey.value=waiting.key;importedReciting.value=false;view.value='practice';}return;
 }
 const chosen=new Set(data.value.importedRecitationIds||[]);
 const unlearned=course.words.filter(w=>isVocabularyWord(w)&&getProgress(data.value,course,w).notebook==='practice');
 let words=unlearned.filter(w=>chosen.has(w.id));if(!words.length)words=unlearned;
 if(!words.length&&pendingConjugations(data.value,course).length){await openConjugationPractice(course);return;}
 if(!words.length)words=course.words.filter(isVocabularyWord);
 if(!words.length)return;
 if(data.value.settings.shuffleLearning)for(let i=words.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[words[i],words[j]]=[words[j],words[i]];}
 const ids=words.map(w=>w.id),order=new Map(ids.map((id,i)=>[id,i])),pool=reviewPackage(data.value);
 pool.words.sort((a,b)=>(order.get(a.id)??Infinity)-(order.get(b.id)??Infinity));
 await begin('direct',ids,pool,true,lessonKey,true);importedReciting.value=false;
}

