async function downloadAudioNames(){
  const p=importPreview.value?.pkg;if(!p)return;
  const entries=p.words.flatMap(w=>{
    const grouped=new Map();for(const f of w.forms){const file=f.audio?.split('/').at(-1)||w.sourceAudio||numberedAudioName(w,f)||simpleAudioName(w,f);if(!grouped.has(file))grouped.set(file,[]);grouped.get(file).push(displayForm(w,f));}
    return [...grouped].map(([file,forms])=>[w.audioNumber||'',forms.join(' / '),file]);
  });
  const rows=[['音频编号','法语词条','录音文件'],...entries];
  const escape=value=>{const raw=String(value);return '"'+(/^[=+@-]/.test(raw)?"'"+raw:raw).replaceAll('"','""')+'"';};
  const csv='\uFEFF'+rows.map(row=>row.map(escape).join(',')).join('\r\n');try{await download(`${p.lesson.id}_录音命名清单.csv`,new TextEncoder().encode(csv),'text/csv');}catch(e){if(e.name!=='AbortError')notice(e.message);}
}
