let reminderTimer,reviewNotification,reminderChecking=false;
async function startNextLesson(){if(nextLesson.value)await openRecitation(nextLesson.value);else{if(currentSession.value?.importedPractice)selectedBookId.value=currentImportedCourse.value?.book.id||selectedBookId.value;navigate('lessons');}}
async function startFavorites(){const from=learningEntryView();if(!data.value.library.some(p=>p.words.some(w=>isVocabularyWord(w)&&data.value.favorites[wordKey(p,w)]))&&pendingConjugations(data.value,null,'favorites').length){await openConjugationPractice(null,'favorites');return;}if(!favoriteWordCount.value&&!hasFavoritesInProgress.value)return;if(await commit(d=>startFavoritePractice(d))){practiceReturnView.value=from;selectedSessionKey.value=MIXED_FAVORITES_KEY;view.value='practice';}}
async function startErrors(){const from=learningEntryView();if(!data.value.library.some(p=>p.words.some(w=>isVocabularyWord(w)&&errorPracticeEligible(data.value,p,w)))&&pendingConjugations(data.value,null,'errors').length){await openConjugationPractice(null,'errors');return;}if(!errorWordCount.value&&!hasErrorsInProgress.value)return;if(await commit(d=>{startErrorPractice(d);acknowledgePractice(d,'errors');})){practiceReturnView.value=from;selectedSessionKey.value=MIXED_ERRORS_KEY;view.value='practice';}}
function reviewCountdown(entry,fr=false){const n=entry.tenseEntry?entry.daysLeft:reviewDaysLeft(data.value,entry.p,entry.w,currentDate.value);return n===null?'—':n===0?(fr?'À réviser':'今天复习'):(fr?'Dans '+n+' j':'剩余 '+n+' 天复习');}
async function setReminderTime(e){const value=e.detail?.value;if(/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(value))await setSetting('reminderTime',value);}
async function toggleNotifications(enabled=!data.value.settings.reviewReminders){
 if(!enabled){await commit(d=>{d.settings.reviewReminders=false;d.settings.notifications=false;});return;}
 await commit(d=>{d.settings.reviewReminders=true;d.settings.notifications=true;});
 try{notificationPermission.value=await allowNotifications();if(notificationPermission.value==='granted'){syncNativeReview(data.value,{force:true});checkReviewReminder();}else notice('请允许应用通知 / Autorisez les notifications.');}catch(e){notice(e.message);}
}

async function laterReview(){if(await commit(d=>snoozeReminder(d))){reviewReminderOpen.value=false;reviewNotification?.close();}}
async function reviewNow(){
  reviewReminderOpen.value=false;if(popupReminderCounts.value.review)await startTodayReview();else if(popupReminderCounts.value.errors){notebookTab.value='errors';await startErrors();}
}
async function checkReviewReminder(){
  clockNow.value=Date.now();
  if(ready.value&&!busy.value&&Object.values(data.value.sessions||{}).some(s=>s.mode==='review'&&(s.reviewDate||s.started)!==day()))await commitProgress(d=>refreshReviewQueues(d));
  if(!ready.value||busy.value||reminderChecking||(!activeReminderCounts.value.review&&!activeReminderCounts.value.errors))return;
  reminderChecking=true;
  try{
    if(activeMode.value==='vocabulary'&&!settingsOpen.value&&!learningAdjustOpen.value&&!modeDrawerOpen.value&&document.visibilityState==='visible'&&shouldRemind(data.value)&&view.value!=='practice'&&!help.value&&!shareOpen.value&&!importOpen.value&&!confirmation.value&&!moveDialog.value&&!reviewDetail.value){const counts=popupCounts(data.value);if(await commit(d=>markReminderShown(d))){popupReminderCounts.value=counts;reviewReminderOpen.value=true;}}
    if(data.value.settings.notifications&&shouldNotifyReview(data.value)){
      try{const counts=notificationCounts(data.value);reviewNotification=notifyReview(counts,()=>{notebookTab.value=counts.review?'review':'errors';navigate('notebook');});if(reviewNotification)await commit(d=>markNotificationSent(d,counts));}catch{notice('通知不可用 / Notifications indisponibles.');}
    }
  }finally{reminderChecking=false;}
}
function onVisibility(){if(document.visibilityState==='hidden')flushPreferences();if(document.visibilityState==='visible'){notificationPermission.value=getNotificationPermission();syncNativeReview(data.value,{force:true});checkReviewReminder();}}
function nativeBack(e){if(learningAdjustOpen.value){closeLearningAdjust();e.preventDefault();return;}if(modeDrawerOpen.value){modeDrawerOpen.value=false;e.preventDefault();return;}if(notebookDrag.value){openNotebookDrag({phase:'cancel'});e.preventDefault();return;}if(confirmation.value){cancelConfirmation();e.preventDefault();return;}if(practiceChoice.value){practiceChoice.value=null;e.preventDefault();return;}const close=document.querySelector('[data-conjugation-close]');if(close){close.click();e.preventDefault();return;}if(view.value==='conjugation'){closeConjugationPractice();e.preventDefault();return;}if(quickImportOpen.value){quickImportOpen.value=false;}else if(modeDrawerOpen.value){modeDrawerOpen.value=false;}else if(importOpen.value){importOpen.value=false;importPreview.value=null;}else if(shareOpen.value)shareOpen.value=false;else if(help.value)help.value=null;else if(confirmation.value)cancelConfirmation();else if(reviewDetail.value)reviewDetail.value=null;else if(moveDialog.value)returnToDefinition();else if(reviewReminderOpen.value)reviewReminderOpen.value=false;else if(settingsOpen.value)settingsOpen.value=false;else if(activeMode.value==='grammar'){if(!grammarMode.value?.handleBack())modeDrawerOpen.value=true;}else if(activeMode.value==='oral')modeDrawerOpen.value=true;else if(view.value==='practice')backFromPractice();else if(view.value==='lesson')view.value='lessons';else if(view.value==='recite')navigate(importedReciting.value?importedOrigin.value:recitationOrigin.value);else if(view.value==='manuals'||view.value==='lessons')navigate('books');else if(view.value!=='books')navigate('books');else return;e.preventDefault();}
function onNativeReview(event){chooseMode('vocabulary');notebookTab.value=event.detail?.notebook==='errors'?'errors':'review';navigate('notebook');}
function onEscape(e){if(e.key==='Escape'){if(learningAdjustOpen.value){closeLearningAdjust();e.preventDefault();return;}if(modeDrawerOpen.value){modeDrawerOpen.value=false;e.preventDefault();return;}if(notebookDrag.value){openNotebookDrag({phase:'cancel'});e.preventDefault();return;}if(confirmation.value){cancelConfirmation();e.preventDefault();return;}if(practiceChoice.value){practiceChoice.value=null;e.preventDefault();return;}const close=document.querySelector('[data-conjugation-close]');if(close){close.click();e.preventDefault();return;}if(view.value==='conjugation'){closeConjugationPractice();e.preventDefault();return;}if(quickImportOpen.value)quickImportOpen.value=false;else if(modeDrawerOpen.value)modeDrawerOpen.value=false;else if(importOpen.value){importOpen.value=false;importPreview.value=null;}else if(shareOpen.value)shareOpen.value=false;else if(help.value)help.value=null;else if(confirmation.value)cancelConfirmation();else if(moveDialog.value)returnToDefinition();else if(reviewDetail.value)reviewDetail.value=null;else if(settingsOpen.value)settingsOpen.value=false;else if(activeMode.value==='grammar'){if(!grammarMode.value?.handleBack())modeDrawerOpen.value=true;}else if(activeMode.value==='oral')modeDrawerOpen.value=true;else if(view.value==='practice')backFromPractice();}}
watch(activeReminderCounts,counts=>{if(!counts.review&&!counts.errors)reviewReminderOpen.value=false;});
let stopAccessibility,stopNotebookHold;onMounted(()=>{stopNotebookHold=installNotebookHold(openNotebookDrag);if(window.chrome?.webview)document.documentElement.classList.add('qihang-desktop');stopAccessibility=accessibleButtons();load();reminderTimer=setInterval(checkReviewReminder,30000);document.addEventListener('visibilitychange',onVisibility);document.addEventListener('keydown',onEscape);window.addEventListener('qihang-back',nativeBack);window.addEventListener('qihang-review-open',onNativeReview);window.addEventListener('qihang-resume',onVisibility);window.addEventListener('dragover',preventBackupNavigation);window.addEventListener('drop',dropBackup);window.addEventListener('qihang-backup',backup);window.addEventListener('qihang-host-close',prepareDesktopClose);});
onUnmounted(()=>{flushPreferences();clearTimeout(notebookSearchTimer);notebookObserver?.disconnect();clearTimeout(notebookDragTimer);stopNotebookHold?.();stopAccessibility?.();clearTimeout(toastTimer);clearInterval(reminderTimer);reviewNotification?.close();document.removeEventListener('visibilitychange',onVisibility);document.removeEventListener('keydown',onEscape);window.removeEventListener('qihang-back',nativeBack);window.removeEventListener('qihang-review-open',onNativeReview);window.removeEventListener('qihang-resume',onVisibility);window.removeEventListener('dragover',preventBackupNavigation);window.removeEventListener('drop',dropBackup);window.removeEventListener('qihang-backup',backup);window.removeEventListener('qihang-host-close',prepareDesktopClose);stopAudio();});
</script>
